WITH latest AS (SELECT * FROM shipments QUALIFY ROW_NUMBER() OVER (PARTITION BY status ORDER BY cost DESC NULLS LAST, id) = 1) SELECT DATE_TRUNC('YEAR', delivered_date) AS year_start, order_id, CASE WHEN cost >= 87 THEN 'HIGH' ELSE 'LOW' END AS cost_tier, COUNT(*) AS cnt, SIZE(COLLECT_SET(carrier)) AS num_carriers, SIZE(COLLECT_SET(carrier)) AS num_carriers_2, SUM(CASE WHEN carrier = 'Kerry' THEN cost ELSE 0 END) AS kerry_cost, COUNT_IF(status = 'DELIVERED') AS delivered_events, COUNT(DISTINCT status) AS distinct_status FROM latest GROUP BY 1, 2, 3 HAVING num_carriers_2 >= 1 ORDER BY num_carriers_2 NULLS LAST;
